INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 16, 'theory', 'Quiz: files');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 0, 'What happens to an existing file on open("a.txt", "w")?', '["It opens for reading", "Its contents are erased right at opening", "Data is appended to the end", "Python raises an error"]', 1, 'Mode w opens the file for writing and wipes it right away, even if you never write anything.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 1, 'Why write with open(...) as f?', '["So the file reads faster", "So the file is closed automatically, even if an error occurs", "To get bytes", "It is required for reading"]', 1, 'with is a context manager: on leaving the block it closes the file in every case.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 2, 'How do you read a file of any size without loading it all into memory?', '["f.read()", "f.readlines()", "for line in f", "list(f.read())"]', 2, 'Looping over a file yields one line at a time; only the current one is in memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 3, 'f.write("hello"); f.write("world"). What ends up in the file?', '["\"hello\" and \"world\" on two lines", "\"helloworld\" on one line", "only \"world\"", "An error"]', 1, 'write does not add a newline: if you need one, you append it yourself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 4, 'What must you specify for a text file so that Russian letters read the same on any system?', '["mode=\"r\"", "encoding=\"utf-8\"", "newline=True", "bytes=False"]', 1, 'Always set the encoding explicitly: the default depends on the system.');
